function taxCalculate(carCC) {
  let totalTax = 0;
  if (carCC <= 600) {
    totalTax = carCC * 0.5;
  } else if (carCC <= 1800) {
    totalTax = 300 + (carCC - 600) * 1.5;
  } else {
    totalTax = 300 + 1800 + (carCC - 1800) * 4;
  }
  return Math.trunc(totalTax);
}

function calculateTax(cc) {
  let tax = 0;
  switch (true) {
    case cc <= 600:
      tax = cc * 0.5;
      break;
    case cc <= 1800:
      tax = 300 + (cc - 600) * 1.5;
      break;
    default:
      tax = 2100 + (cc - 1800) * 4;
  }
  return Math.trunc(tax);
}

